UPDATE tbl_transaction
   SET category_id = #{categoryId},
       category_source = #{categorySource}
 WHERE id = #{id}
   AND (category_source IS NULL OR category_source <> 'USER')

mapper.select:
SELECT id
  FROM tbl_transaction
 WHERE codef_tr_key = #{codefTrKey}

mapper.update:
UPDATE tbl_transaction
   SET category_id = #{categoryId},
       category_source = 'USER'
 WHERE id = #{id}
   AND user_id = #{userId}

mapper.select:
SELECT COALESCE(SUM(), 0)
  FROM tbl_transaction
 WHERE user_id = #{userId}
   AND classification = 'CONSUMPTION'
   AND is_excluded_from_summary = 0
   AND tr_date >= #{startDate}
   AND tr_date <  #{endDate}

SELECT COALESCE(SUM(amount), 0)
  FROM tbl_transaction
 WHERE user_id = #{userId}
   AND classification = 'INCOME'
   AND is_excluded_from_summary = 0
   AND tr_date >= #{startDate}
   AND tr_date <  #{endDate}

SELECT t.id, t.tr_date, t.merchant_name, cat.category_name, t.classification, t.amount, t.is_refund, t.refunded_amount, t.direction, t.source_type, card.card_type_code, card.institution_name AS card_institution_name, acc.bank_name AS account_bank_name FROM tbl_transaction t LEFT JOIN tbl_category cat ON cat.id = t.category_id LEFT JOIN tbl_card card ON card.id = t.card_id LEFT JOIN tbl_connected_account acc ON acc.id = t.account_id WHERE t.user_id = #{userId} AND t.is_excluded_from_summary = 0
AND t.tr_date >= #{startDate} AND t.tr_date < #{endDate}
ORDER BY t.tr_date DESC, t.id DESC
